#!/usr/bin/env python3
"""Package saved CameraE2E design evidence as one offline Korean demo report."""
from __future__ import annotations

import base64
import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'reports/camera-design-demo-20261012'
RUNS = Path('/Volumes/T7/CameraE2E/reference-workshop')
evidence = {'schema': 'camera_design_demo_report_v1', 'generated_at': datetime.now(timezone.utc).isoformat(),
            'scope': 'Saved model evidence; report packaging only; no new simulation or physical validation',
            'source_files': [], 'embedded_images': [], 'raw_identity': []}


def sha(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()


def load(rel):
    p = ROOT / rel
    evidence['source_files'].append({'path': str(p.relative_to(ROOT)), 'sha256': sha(p)})
    return json.loads(p.read_text())


manifests = {}


def manifest(run):
    if run not in manifests:
        p = RUNS / run / 'manifest.json'
        manifests[run] = json.loads(p.read_text())['files']
        evidence.setdefault('run_manifests', []).append({'run_id': run, 'path': str(p), 'sha256': sha(p)})
    return manifests[run]


def image(run, rel):
    p = RUNS / run / rel
    digest = sha(p)
    assert digest == manifest(run)[rel], f'Image hash mismatch: {p}'
    evidence['embedded_images'].append({'run_id': run, 'file': rel, 'sha256': digest})
    return 'data:image/png;base64,' + base64.b64encode(p.read_bytes()).decode()


def summarize(run, summary, prefix=''):
    fields = {}
    for f in summary['fields']:
        if f['id'] not in ('center', 'outer-ne'):
            continue
        mtf = f['optics']['mtf']
        j = min(range(len(mtf['cycles_per_native_pixel'])), key=lambda i: abs(mtf['cycles_per_native_pixel'][i] - .125))
        assert abs(mtf['cycles_per_native_pixel'][j] - .125) < 1e-9
        fields[f['id']] = {'metrics': f['metrics'], 'noise': f['tests']['noise']['uniform']['processed']['temporal_std'],
            'mtf': {'radial': mtf['radial'][j], 'tangential': mtf['tangential'][j]},
            'images': {chart: image(run, prefix + f['images'][chart]['display']) for chart in ('color', 'texture', 'resolution')}}
    return {'run': run, 'configuration': summary['configuration'], 'fields': fields}


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    records = {x['label']: x for x in load('outputs/reference-workshop-delivery-20261011/runs.json')}
    verification = load('outputs/reference-workshop-delivery-20261011/verification.json')
    delivery = load('outputs/reference-workshop-delivery-20261011/delivery.json')
    tuning = load('outputs/reference-isp-tuning-20261012/delivery.json')
    tuning_verification = load('outputs/reference-isp-tuning-20261012/verification.json')
    saved_profile = load('outputs/reference-isp-tuning-20261012/saved-profile.json')
    ircf = load('outputs/reference-ircf-lab-20261012/findings.json')
    readout = load('outputs/reference-readout-lab-20261012/verification.json')
    ghost = load('outputs/reference-ghost-probes-20261012/verification.json')
    library = load('outputs/design-library-delivery-20261012/delivery.json')
    assert verification['status'] == 'verified' and not verification['failures']
    assert tuning_verification['status'] == 'verified'
    data = {'runs': {}, 'tuning': tuning['selection'], 'tuning_url': tuning['url'], 'demos': delivery['demo_urls']}
    for key, label in [('base', 'low-light'), ('lens', 'low-light-lens'), ('lsc', 'low-light-lsc'), ('nr', 'low-light-lsc-denoise')]:
        r = records[label]
        assert r['status'] == 'succeeded'
        assert sha(RUNS / r['id'] / 'manifest.json') == r['result']['summary']['manifest_sha256']
        data['runs'][key] = summarize(r['id'], r['result']['summary'])
    cfa = records['low-light-cfa']
    assert sha(RUNS / cfa['id'] / 'manifest.json') == cfa['result']['summary']['manifest_sha256']
    for idx, c in enumerate(cfa['result']['summary']['candidates']):
        data['runs']['cfa' + str(idx)] = summarize(cfa['id'], c, c['id'] + '/')

    # Read the actual stored RAW bytes, not only the historical verification receipt.
    baseline = records['low-light']['id']
    for label in ('low-light-lsc', 'low-light-lsc-denoise'):
        run = records[label]['id']
        checked = 0
        for rel, digest in manifest(baseline).items():
            if not rel.endswith('.npy') or '/raw-' not in rel or '/._' in rel:
                continue
            assert sha(RUNS / baseline / rel) == digest == manifest(run)[rel] == sha(RUNS / run / rel)
            checked += 1
        assert checked == 288
        evidence['raw_identity'].append({'source': baseline, 'replay': run, 'files_checked': checked, 'status': 'byte_identical'})

    data['layout'] = image(baseline, 'optics/layout.png')
    data['hero'] = data['runs']['lsc']['fields']['outer-ne']['images']['color']
    data['tuning_images'] = {i: image(tuning['study_run_id'], f'{i}/fields/outer-ne/texture/display.png') for i in ['candidate-00', 'candidate-04', 'candidate-05']}
    data['ircf_images'] = [image(ircf['run_id'], f'cases/{i}/baseline.png') for i in ['case-008', 'case-011']]
    data['readout_images'] = [image('run-437af9329d9f4fcf88d53d457f024c3b', f'cases/case-003/{i}/temporal-residual.png') for i in ['pixel_iid', 'column_noise', 'cds_correlated']]
    data['ghost_images'] = [image('run-048e91d2ba0f4a88bc6c3896b5fd8f3c', f'cases/case-011/{i}.png') for i in ['source_off', 'with_ghost']]
    data['cfa_rows'] = [{'scale': r['configuration']['pixel']['cfa_thickness_scale'], **r['fields']['outer-ne']['metrics']} for k, r in data['runs'].items() if k.startswith('cfa')]
    evidence['historical_checks'] = {'workshop': {'checks': len(verification['checks']), 'files': verification['files_verified'], 'raw_copies': verification['raw_arrays_verified']}, 'tuning': tuning_verification['status'], 'ircf': ircf['verification_status'], 'readout': readout['status'], 'ghost_refinement': ghost['refinement']['status']}
    evidence['selection'] = tuning['selection']
    evidence['selected_profile'] = saved_profile['specification']['isp']
    evidence['library_snapshot'] = library['counts']
    evidence['data'] = {k: v for k, v in data.items() if k not in ['runs', 'hero', 'layout', 'tuning_images', 'ircf_images', 'readout_images', 'ghost_images']}
    evidence['run_metrics'] = {key: {'run_id': value['run'], 'configuration': value['configuration'], 'fields': {fid: {k: v for k, v in f.items() if k != 'images'} for fid, f in value['fields'].items()}} for key, value in data['runs'].items()}
    data['evidence'] = evidence
    output = TEMPLATE.replace('__DATA__', json.dumps(data, ensure_ascii=False).replace('</', '<\\/'))
    (OUT / 'index.html').write_text(output)
    (OUT / 'evidence.json').write_text(json.dumps(evidence, ensure_ascii=False, indent=2) + '\n')
    print(json.dumps({'html': str(OUT / 'index.html'), 'bytes': len(output.encode()), 'embedded_images': len(evidence['embedded_images']), 'raw_identity_checks': sum(x['files_checked'] for x in evidence['raw_identity'])}, ensure_ascii=False))


